local SLogger = {}
local _settings = {}

SLogger.__userId = nil
SLogger.__systemNameCache = nil

-- 初始化
function SLogger.Init(userId: number?, loggerManager, systemNameCache)
	_settings = loggerManager.GetSettings()
	SLogger.__userId = userId
	SLogger.__systemNameCache = systemNameCache
end

-- 日志记录器名称
local function logHandler(handler: (name: string) -> ())
	local name = SLogger.__systemNameCache()
	if SLogger.__userId then
		name = `{name} {SLogger.__userId}`
	end
	handler(name)
end

-- 杂项日志
function SLogger.Verbose(handler: (name: string) -> ())
	if _settings.Level <= 1 then
		logHandler(handler)
	end
end

-- 调试日志
function SLogger.Debug(handler: (name: string) -> ())
	if _settings.Level <= 2 then
		logHandler(handler)
	end
end

-- 信息日志
function SLogger.Info(handler: (name: string) -> ())
	if _settings.Level <= 3 then
		logHandler(handler)
	end
end

-- 警告日志
function SLogger.Warn(handler: (name: string) -> ())
	if _settings.Level <= 4 then
		logHandler(handler)
	end
end

-- 杂项日志
function SLogger.verbose(handler: (name: string) -> ())
	if _settings.Level <= 1 then
		logHandler(handler)
	end
end

-- 调试日志
function SLogger.debug(handler: (name: string) -> ())
	if _settings.Level <= 2 then
		logHandler(handler)
	end
end

-- 信息日志
function SLogger.info(handler: (name: string) -> ())
	if _settings.Level <= 3 then
		logHandler(handler)
	end
end

-- 警告日志
function SLogger.warn(handler: (name: string) -> ())
	if _settings.Level <= 4 then
		logHandler(handler)
	end
end

return SLogger
